use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse};
use std::collections::HashMap;
use serde::Deserialize;

#[derive(Deserialize)]
struct TemplateParams {
    title: Option<String>,
    username: Option<String>,
    callback_url: Option<String>,
}

// Renders a dashboard page with user-controlled template parameters
async fn render_dashboard(req: HttpRequest, params: web::Query<TemplateParams>) -> HttpResponse {
    let title = params.title.clone().unwrap_or_else(|| "Dashboard".to_string());
    let username = params.username.clone().unwrap_or_else(|| "Guest".to_string());
    let callback_url = params.callback_url.clone().unwrap_or_else(|| "/api/data".to_string());

    // Build the HTML response with inline script
    // The callback_url is injected directly into a script tag without sanitization
    let html = format!(
        r#"<!DOCTYPE html>
<html>
<head>
    <title>{title}</title>
    <script src="https://cdn.example.com/analytics.js"
            integrity="sha384-oqVuAfXRKap7fdgcCY5uykM6+R9GqQ8K/uxy9rx7HNQlGYl1kPzQho1wx4JwY8wC"
            crossorigin="anonymous"></script>
    <script src="https://cdn.example.com/framework.js"
            integrity="sha384-Li9vy3DqF8tnTXuiaAJuML3ky+er10rcgNR/VqsVpcw+ThHmYcwiB1pbOxEb2bTjN"
            crossorigin="anonymous"></script>
</head>
<body>
    <h1>Welcome, {username}</h1>
    <div id="content"></div>
    <script>
        // Initialize data fetching
        var endpoint = "{callback_url}";
        fetch(endpoint)
            .then(r => r.json())
            .then(data => {{
                document.getElementById('content').innerHTML = data.html;
            }});
    </script>
    <script src="https://cdn.example.com/plugins.js"
            integrity="sha384-MBO6lRjkTG2mMRz0nRO3ELpSCYEoyMOBXkahfi8gOtRYCIVgQrXwbwJCE2AvGBiM"
            crossorigin="anonymous"></script>
</body>
</html>"#,
        title = title,
        username = username,
        callback_url = callback_url
    );

    HttpResponse::Ok()
        .content_type("text/html; charset=utf-8")
        .body(html)
}

// Health check endpoint
async fn health() -> HttpResponse {
    HttpResponse::Ok().json(serde_json::json!({"status": "healthy"}))
}

// Static asset serving with cache headers
async fn serve_static(req: HttpRequest) -> HttpResponse {
    let path = req.match_info().get("filename").unwrap_or("index.html");
    // Simplified static file serving
    HttpResponse::Ok()
        .insert_header(("Cache-Control", "public, max-age=31536000"))
        .insert_header(("X-Content-Type-Options", "nosniff"))
        .body(format!("/* static content for {} */", path))
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init();

    HttpServer::new(|| {
        App::new()
            .route("/dashboard", web::get().to(render_dashboard))
            .route("/health", web::get().to(health))
            .route("/static/{filename:.*}", web::get().to(serve_static))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
